import pandas as pd

train = pd.read_csv('b3_te_zt_extrapolation_train.csv')
train = train.drop(299)
top = train.nlargest(15, 'target')

for idx, row in top.iterrows():
    comp = []
    for col in train.columns:
        if col not in ['T', 'target'] and row[col] > 0:
            comp.append(f"{col}: {row[col]:.4f}")
    print(f"T={row['T']}, ZT={row['target']:.4f} : " + ", ".join(comp))

import pandas as pd
pool = pd.read_csv('b3_te_zt_extrapolation_pool.csv')
for idx, row in pool[pool['Sn'] > 0.4].iterrows():
    comp = []
    for col in pool.columns:
        if col not in ['candidate_id', 'T'] and row[col] > 0:
            comp.append(f"{col}: {row[col]:.4f}")
    print(f"{row['candidate_id']}: " + ", ".join(comp))

